schema_ddl:
CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE,
    email TEXT
);

CREATE TABLE prodotti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    descrizione TEXT,
    codice_prodotto TEXT NOT NULL UNIQUE
);

CREATE TABLE prezzi_prodotti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    prezzo NUMERIC(10,2) NOT NULL CHECK (prezzo >= 0),
    periodo_validita DATERANGE NOT NULL
);

CREATE INDEX idx_prezzi_prodotti_periodo ON prezzi_prodotti USING GIST (periodo_validita);
